55	long sys_mmap(unsigned long addr, unsigned long length, long prot, long flags,
56	             long fd, long offset)
57	{
58	  (void) addr;
59	  /* Every page is already RWX -- no MMU to restrict with -- EXCEPT prot
60	   * still decides whether a MAP_SHARED file mapping is safe to serve
61	   * below (a read-only one is; see there). */
62	  if (length == 0) return -EINVAL;
63	
64	  const uint64_t need = ((uint64_t) length + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);
65	  if (need > g_mmap_top - g_mmap_floor) return -ENOMEM;
66	  g_mmap_top -= need;
67	  void* base = (void*) (uintptr_t) g_mmap_top;
68	
69	  if (flags & MAP_ANONYMOUS) {
70	    memset(base, 0, need);
71	    return (long) (uintptr_t) base;
72	  }
73	
74	  /* File-backed (ROADMAP_LINUX_RUNTIME.md U7): read the file's
75	   * [offset, offset+length) range into the freshly-allocated arena
76	   * space, a private owned copy. MAP_SHARED without PROT_WRITE is
77	   * accepted too -- llama.cpp's own mmap loader (llama-mmap.cpp) uses
78	   * exactly this (MAP_SHARED, PROT_READ only) -- because a mapping
79	   * nothing ever writes through has no OBSERVABLE difference between
80	   * MAP_PRIVATE and MAP_SHARED (the distinction is entirely about write
81	   * visibility). A writable MAP_SHARED request has no write-back path
82	   * here and is refused (-ENOSYS) rather than silently downgraded to a
83	   * private copy a caller might rely on staying shared. */
84	  if (flags & MAP_SHARED) {
85	    if (prot & PROT_WRITE) return -ENOSYS;
86	  } else if (!(flags & MAP_PRIVATE)) {
87	    return -ENOSYS;
88	  }
89	  const ssize_t n = htif_pread(fd, base, length, offset);
90	  if (n < 0) return n;
91	  if ((size_t) n < need) memset((char*) base + n, 0, need - (size_t) n);
92	  return (long) (uintptr_t) base;
93	}
94	
95	long sys_munmap(unsigned long addr, unsigned long length)
96	{
97	  (void) addr;
98	  (void) length;
99	  return 0;
100	}
101	
102	long sys_mprotect(unsigned long addr, unsigned long length, long prot)
103	{
104	  (void) addr;
105	  (void) length;
106	  (void) prot;
107	  return 0;
108	}
109	
110	long sys_mremap(unsigned long old_addr, unsigned long old_size,
111	                unsigned long new_size, unsigned long flags)
112	{
113	  (void) old_addr;
114	  (void) old_size;
115	  (void) new_size;
116	  (void) flags;
117	  return -ENOMEM;
118	}
