239	/* Linux (generic riscv64) open(2) flag bits -> newlib's BSD-derived bits,
240	 * the wire format the HTIF host's open/openat handlers expect (see
241	 * andes_ae350.c andesim_newlib_open_flags and the vsim mirror). The two
242	 * ABIs assign completely different bit positions to O_CREAT/O_TRUNC/etc
243	 * (only the low 2 access-mode bits agree) -- passing Linux bits through
244	 * untranslated drops O_CREAT silently and fopen(path,"w") fails ENOENT.
245	 * O_DIRECTORY/O_CLOEXEC have no newlib equivalent and are dropped: this
246	 * relay has one host-side fd per guest fd and never execs, so neither
247	 * bit changes observable behavior here. */
248	static int linux_to_newlib_open_flags(int lf)
249	{
250	  int nf = lf & 0x3; /* O_RDONLY/WRONLY/RDWR: 0/1/2, identical in both */
251	  if (lf & 0x400) nf |= 0x0008;  /* O_APPEND */
252	  if (lf & 0x40)  nf |= 0x0200;  /* O_CREAT */
253	  if (lf & 0x200) nf |= 0x0400;  /* O_TRUNC */
254	  if (lf & 0x80)  nf |= 0x0800;  /* O_EXCL */
255	  if (lf & 0x800) nf |= 0x4000;  /* O_NONBLOCK */
256	  if (lf & 0x100) nf |= 0x8000;  /* O_NOCTTY */
257	  return nf;
258	}
