480	int handle_ecall(unsigned long* regs)
481	{
482	  const unsigned long nr = regs[REG_A7];
483	  long ret = 0;
484	
485	  switch (nr) {
486	    case SYS_write:
487	      ret = _write((int) regs[REG_A0], (const void*) regs[REG_A1],
488	                  (size_t) regs[REG_A2]);
489	      break;
490	    case SYS_writev:
491	      ret = sys_writev((int) regs[REG_A0],
492	                       (const struct vlinux_iovec*) regs[REG_A1],
493	                       (int) regs[REG_A2]);
494	      break;
495	
496	    case SYS_openat:
497	      ret = sys_openat((int) regs[REG_A0], (const char*) regs[REG_A1],
498	                       (int) regs[REG_A2], (int) regs[REG_A3]);
499	      break;
500	    case SYS_close:
501	      ret = htif_syscall(VH_SYS_CLOSE, regs[REG_A0], 0, 0, 0);
502	      break;
503	    case SYS_read:
504	      ret = _read((int) regs[REG_A0], (void*) regs[REG_A1],
505	                  (size_t) regs[REG_A2]);
506	      break;
507	    case SYS_pread64:
508	      ret = sys_pread64((int) regs[REG_A0], (void*) regs[REG_A1],
509	                        (unsigned long) regs[REG_A2], (long) regs[REG_A3]);
510	      break;
511	    case SYS_lseek:
512	      ret = htif_syscall(VH_SYS_LSEEK, regs[REG_A0], regs[REG_A1],
513	                         regs[REG_A2], 0);
514	      break;
515	    case SYS_fstat:
516	      ret = sys_fstat((int) regs[REG_A0], (struct vlinux_stat*) regs[REG_A1]);
517	      break;
518	    case SYS_fstatat:
519	      ret = sys_fstatat((int) regs[REG_A0], (const char*) regs[REG_A1],
520	                        (struct vlinux_stat*) regs[REG_A2], (int) regs[REG_A3]);
521	      break;
522	    case SYS_statx:
523	      ret = sys_statx((int) regs[REG_A0], (const char*) regs[REG_A1],
524	                      (int) regs[REG_A2], (struct vlinux_statx*) regs[REG_A4]);
525	      break;
526	    case SYS_faccessat:
527	      ret = sys_faccessat((int) regs[REG_A0], (const char*) regs[REG_A1],
528	                          (int) regs[REG_A2]);
529	      break;
530	    case SYS_getcwd:
531	      ret = sys_getcwd((char*) regs[REG_A0], (unsigned long) regs[REG_A1]);
532	      break;
533	    case SYS_fadvise64:
534	    case SYS_madvise:
535	      ret = 0; /* access-pattern hints (readahead/willneed/dontneed, ...):
536	                * everything is already eagerly resident, nothing to tune */
537	      break;
538	    case SYS_readlinkat:
539	      ret = -EINVAL; /* no symlinks in this filesystem relay: never one */
540	      break;
541	    case SYS_getdents64:
542	      ret = -ENOSYS; /* no directory-listing primitive on the HTIF window */
543	      break;
544	
545	    case SYS_clock_gettime:
546	      ret = sys_clock_gettime((int) regs[REG_A0],
547	                              (struct vlinux_timespec*) regs[REG_A1]);
548	      break;
549	    case SYS_clock_getres:
550	      ret = sys_clock_getres((int) regs[REG_A0],
551	                             (struct vlinux_timespec*) regs[REG_A1]);
552	      break;
553	    case SYS_nanosleep:
554	    case SYS_clock_nanosleep:
555	      ret = 0; /* no timer exists: every sleep "completes" immediately,
556	                * burning no sim time (ROADMAP_LINUX_RUNTIME.md U6) */
557	      break;
558	
559	    case SYS_exit:
560	    case SYS_exit_group:
561	      _exit((int) regs[REG_A0]); /* noreturn */
562	
563	    case SYS_brk:
564	      ret = sys_brk(regs[REG_A0]);
565	      break;
566	    case SYS_mmap:
567	      ret = sys_mmap(regs[REG_A0], regs[REG_A1], (long) regs[REG_A2],
568	                     (long) regs[REG_A3], (long) regs[REG_A4],
569	                     (long) regs[REG_A5]);
570	      break;
571	    case SYS_munmap:
572	      ret = sys_munmap(regs[REG_A0], regs[REG_A1]);
573	      break;
574	    case SYS_mprotect:
575	      ret = sys_mprotect(regs[REG_A0], regs[REG_A1], (long) regs[REG_A2]);
576	      break;
577	    case SYS_mremap:
578	      ret = sys_mremap(regs[REG_A0], regs[REG_A1], regs[REG_A2], regs[REG_A3]);
579	      break;
580	
581	    case SYS_set_tid_address:
582	      ret = 1; /* the fixed "tid" every getpid/gettid call also reports */
583	      break;
584	    case SYS_futex:
585	      /* Single hart, single thread (ROADMAP_LINUX_RUNTIME.md: clone is
586	       * -ENOSYS, apps run -t 1): no real contention can ever exist, so
587	       * every op is answered 0 -- FUTEX_WAIT: "already available" (a
588	       * spurious wake glibc's mutex/condvar loops are required by the
589	       * futex(2) contract to tolerate and re-check, so this is spec-legal,
590	       * not a shortcut); FUTEX_WAKE(_BITSET): "0 waiters woken" (there
591	       * are never any real waiters to wake); FUTEX_LOCK_PI/TRYLOCK_PI/
592	       * UNLOCK_PI: "success" (0 is their success code too). Without this,
593	       * glibc's OWN internal locking (malloc arena, static-init guards --
594	       * used pervasively even in a single-threaded process, not just for
595	       * explicit threading) hits ENOSYS and __libc_fatal()s with "The
596	       * futex facility returned an unexpected error code." before
597	       * main() is ever reached. */
598	      ret = 0;
599	      break;
600	    case SYS_set_robust_list:
601	      ret = 0;
602	      break;
603	    case SYS_rseq:
604	      ret = -ENOSYS; /* deliberate: restartable sequences, glibc falls back */
605	      break;
606	
607	    case SYS_uname:
608	      sys_uname((struct vlinux_utsname*) regs[REG_A0]);
609	      ret = 0;
610	      break;
611	
612	    case SYS_getpid:
613	    case SYS_gettid:
614	      ret = 1;
615	      break;
616	    case SYS_getuid:
617	    case SYS_geteuid:
618	    case SYS_getgid:
619	    case SYS_getegid:
620	      ret = 0;
621	      break;
622	
623	    case SYS_sysinfo:
624	      sys_sysinfo((struct vlinux_sysinfo*) regs[REG_A0]);
625	      ret = 0;
626	      break;
627	
628	    case SYS_prlimit64: {
629	      /* {rlim_cur, rlim_max}, both u64 -- old_limit is regs[REG_A3]; report
630	       * unlimited rather than modeling real per-resource limits. */
631	      unsigned long* old_limit = (unsigned long*) regs[REG_A3];
632	      if (old_limit) {
633	        old_limit[0] = ~0ul; /* RLIM_INFINITY */
634	        old_limit[1] = ~0ul;
635	      }
636	      ret = 0;
637	      break;
638	    }
639	    case SYS_getrandom: {
640	      unsigned char* buf = (unsigned char*) regs[REG_A0];
641	      const unsigned long len = regs[REG_A1];
642	      unsigned long seed;
643	      asm volatile("csrr %0, mcycle" : "=r"(seed)); /* see stack.c: mcycle,
644	                                                       * not rdcycle/rdtime */
645	      for (unsigned long i = 0; i < len; ++i) {
646	        seed = seed * 6364136223846793005ul + 1442695040888963407ul;
647	        buf[i] = (unsigned char) (seed >> 33);
648	      }
649	      ret = (long) len;
650	      break;
651	    }
652	
653	    case SYS_sched_getaffinity: {
654	      const unsigned long cpusetsize = regs[REG_A1];
655	      unsigned char* mask = (unsigned char*) regs[REG_A2];
656	      if (cpusetsize < 1) {
657	        ret = -EINVAL;
658	        break;
659	      }
660	      mask[0] = 0x1; /* 1 cpu, bit 0 */
661	      for (unsigned long i = 1; i < cpusetsize; ++i) mask[i] = 0;
662	      ret = (long) cpusetsize;
663	      break;
664	    }
665	    case SYS_sched_yield:
666	      ret = 0; /* nothing else to yield to (single-threaded) */
667	      break;
668	
669	    case SYS_rt_sigaction:
670	    case SYS_rt_sigprocmask:
671	    case SYS_sigaltstack:
672	      ret = 0; /* recorded nowhere: no signal delivery exists to honor them */
673	      break;
674	    case SYS_tgkill:
675	      _exit(128 + (int) regs[REG_A2]); /* noreturn: a fatal signal to self */
676	
677	    case SYS_ioctl:
678	      ret = -ENOTTY; /* every fd here is UART/SimControl, never a real tty */
679	      break;
680	    case SYS_fcntl:
681	      ret = 0; /* basic: accept every fd-flag query/set as a no-op success */
682	      break;
683	
684	    default:
685	      if (!enosys_already_seen(nr)) printf("vlinux: ENOSYS %lu\n", nr);
686	      ret = -ENOSYS;
687	      break;
688	  }
689	
690	  regs[REG_A0] = (unsigned long) ret;
691	  regs[REG_MEPC] += 4; /* skip the ecall on return */
692	  return 1;
693	}
